-- =====================================================================
-- DEMO DATA for the 3-minute run (docs/DEMO.md). Run AFTER 19. Generated by a script from the
-- live data; safe to re-run (it does nothing the second time). Nothing existing is changed or
-- removed: it only adds orders, every one labeled (orders.is_demo).
--
-- What it plants, and why:
--   100 weekday lunch orders (Bun Bo Hue + Ca Phe Sua Da) on 2026-10-05, 2026-10-07, 2026-10-08, 2026-10-09.
--     They raise the 28 days before the last 14, so weekday lunch now reads about 13.5% down
--     (the real data alone shows 3.1%).
--   4 weekday dinner orders (Pho Dac Biet) on 2026-10-15, 2026-10-16, 2026-10-19, 2026-10-21, 2026-10-22, so weekday dinner
--     stays under the 10% dip threshold and lunch is the story.
-- The windows hold for a demo between Oct 25 and Oct 28, 2026.
-- =====================================================================

alter table orders add column if not exists is_demo boolean not null default false;

do $$
declare
  oid bigint;
begin
  if not exists (select 1 from orders where restaurant_id = 1 and is_demo) then
  end if;

end $$;
